package com.ethk3.novaonepro.strategyv2;
import com.ethk3.novaonepro.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Actual Runtime.halt and fresh JVM native SQLite recovery; not Android process-kill evidence. */
public final class AtomPublicationProcessHost {
 static void need(boolean b,String m){AtomPublicationNativeHost.need(b,m);}
 static ResearchWriteQueueR27.Batch source(ReplayDatasetR27 d){ResearchWriteQueueR27.Batch b=new ResearchWriteQueueR27.Batch();for(int t=AtomReplayR27.MIN_ROWS;t<AtomReplayR27.MIN_ROWS+12;t++){AtomReplayR27.Frame f=AtomReplayR27.build(d,t,t+1);for(int p=0;p<10;p++){double[] x=AtomNetR27.positionedInput(AtomReplayR27.features(f.values[p],f.present[p],true),p+1);AtomNetStoreR30.sample(b,d.datasetHash,(t-AtomReplayR27.MIN_ROWS)*10+p,d.issues[t],p+1,x,f.hit[p],f.actual[p]-1);}}return b;}
 public static void main(String[] args)throws Exception{File path=new File(args[0]);String mode=args[1];AtomPublicationNativeHost.setup(path);Path expectedOld=path.toPath().resolveSibling("expected-old.bin"),expectedNew=path.toPath().resolveSibling("expected-new.bin"),parentFile=path.toPath().resolveSibling("expected-parent.txt");ReplayDatasetR27 data=AtomPublicationNativeHost.data();
  if(mode.startsWith("halt-")){AtomNetSessionR30 old=AtomPublicationNativeHost.init(data);Files.write(expectedOld,old.encode());String parent=AtomNetPublicationR31.currentStateHash(AtomPublicationNativeHost.db);Files.write(parentFile,parent.getBytes(java.nio.charset.StandardCharsets.UTF_8));ResearchWriteQueueR27.Batch b=new ResearchWriteQueueR27.Batch();AtomNetSessionR30 next=AtomPublicationNativeHost.materialize(data,b);Files.write(expectedNew,next.encode());try(MemoryBudgetR31.Lease work=AtomNetPublicationR31.workReservationR31(next);AtomNetPublicationR31.Prepared p=AtomNetPublicationR31.prepare(AtomPublicationNativeHost.store,AtomPublicationNativeHost.db,b,next,System.currentTimeMillis(),parent)){AtomPublicationNativeHost.stage(p);p.verifyPrepared(AtomPublicationNativeHost.db);Map<String,Object> event=new LinkedHashMap<>();event.put("pid",ProcessHandle.current().pid());event.put("mode",mode);event.put("publication",p.id);event.put("stateHash",p.stateHash);event.put("currentMaterializedBeforeFinal",AtomNetStoreR30.restore(AtomPublicationNativeHost.db).materializedSamples);event.put("phase",mode.equals("halt-before-final")?"DURABLE_PREPARED_BEFORE_FINAL_CAS":"NEXT_WRITE_REAL_AFTER_COMMIT_HALT_HOOK");System.out.println(JsonR27.write(event));System.out.flush();if(mode.equals("halt-before-final"))Runtime.getRuntime().halt(71);AtomNativeFaultsR31.haltAfterCommit();AtomPublicationNativeHost.submit("ATOMNET_PROCESS_FINAL",AtomPublicationNativeHost.frozen("ATOMNET_PROCESS_FINAL",p.publicationBatch(b,next),p.id+":final",501));throw new AssertionError("real halt did not execute");}}
  else{byte[] old=Files.readAllBytes(expectedOld),expected=Files.readAllBytes(expectedNew);AtomNetSessionR30 restored=AtomNetStoreR30.restore(AtomPublicationNativeHost.db);if(mode.equals("recover-before")){need(Arrays.equals(old,restored.encode()),"fresh JVM before-final keeps exact old optimizer/RNG/cursor");need(AtomPublicationNativeHost.n("SELECT count(*) FROM r31_atomnet_publication WHERE sample_count=120 AND status='PUBLISHED'")==0,"prepared samples not published by process death");}else need(Arrays.equals(expected,restored.encode()),"fresh JVM after durable final restores exact new optimizer/RNG/cursor");
   AtomPublicationNativeHost.owner("owner-B",2);AtomNetSessionR30 next=AtomNetSessionR30.decode(expected,StatsR27.sha256(expected));String parent=new String(Files.readAllBytes(parentFile),java.nio.charset.StandardCharsets.UTF_8);ResearchWriteQueueR27.Batch b=source(data);try(MemoryBudgetR31.Lease work=AtomNetPublicationR31.workReservationR31(next);AtomNetPublicationR31.Prepared p=AtomNetPublicationR31.prepare(AtomPublicationNativeHost.store,AtomPublicationNativeHost.db,b,next,System.currentTimeMillis(),parent)){AtomPublicationNativeHost.stage(p);p.verifyPrepared(AtomPublicationNativeHost.db);DatabaseCoordinator.CommitResultR31<Integer> result=AtomPublicationNativeHost.submit("ATOMNET_PROCESS_FINAL",AtomPublicationNativeHost.frozen("ATOMNET_PROCESS_FINAL",p.publicationBatch(b,next),p.id+":final",501));need(result.replay==mode.equals("recover-after"),"fresh owner replays only an actual committed final receipt");}
   need(Arrays.equals(expected,AtomNetStoreR30.restore(AtomPublicationNativeHost.db).encode()),"cross-JVM resume or replay publishes exactly one complete state");need(AtomPublicationNativeHost.n("SELECT count(*) FROM r31_atomnet_sample_stage")==120&&AtomPublicationNativeHost.n("SELECT count(*) FROM r31_atomnet_publication WHERE sample_count=120 AND status='PUBLISHED'")==1,"cross-JVM recovery never duplicates samples or publication");need(AtomNetStoreR30.samples(AtomPublicationNativeHost.db,next).get(0).x.length==next.input,"actual new-JVM consumer reads restored sample ref");Map<String,Object> out=new LinkedHashMap<>();out.put("status","FRESH_JVM_NATIVE_RECOVERY_PASS");out.put("mode",mode);out.put("pid",ProcessHandle.current().pid());out.put("assertions",AtomPublicationNativeHost.checks);out.put("stateHash",StatsR27.sha256(expected));out.put("samples",120);out.put("declaredOriginalSplitPlan",Arrays.asList(800,400,160));out.put("scope","REAL_HOST_JVM_HALT_AND_NEW_JVM_NATIVE_SQLITE_FILE_CAS_NOT_ANDROID_PROCESS_KILL_NOT_QUALITY");AtomPublicationNativeHost.db.close();System.out.println(JsonR27.write(out));}
 }
}
